#!/bin/bash
# PORTMASTER: offtheroad, Off The Road.sh
# Off The Road — generated by nxbootstrap 0.6.37.
NXBOOTSTRAP_FINISHED=0
NXBOOTSTRAP_ABORTING=0
NXBOOTSTRAP_EARLY_LOG_ACTIVE=1
NXBOOTSTRAP_LAUNCHER_DIR=""
NXBOOTSTRAP_HEALTH_FILE=""
NXBOOTSTRAP_FALLBACK_LOCK_ACQUIRED=0
NXBOOTSTRAP_FALLBACK_LOCK_DIR=""
NXBOOTSTRAP_FALLBACK_LOCK_TOKEN=""
nxbootstrap_finish() {
  [ "$NXBOOTSTRAP_FINISHED" = 0 ] || return 0
  NXBOOTSTRAP_FINISHED=1
  if command -v pm_finish >/dev/null 2>&1; then pm_finish || true; fi
}
nxbootstrap_write_early_log() {
  local status=$1 log_dir log_path
  [ "$NXBOOTSTRAP_EARLY_LOG_ACTIVE" = 1 ] && [ "$status" -ne 0 ] 2>/dev/null || return 0
  for log_dir in "${GAMEDIR:-}" "$NXBOOTSTRAP_LAUNCHER_DIR" \
    "${XDG_RUNTIME_DIR:-}" "${TMPDIR:-/tmp}"; do
    [ -n "$log_dir" ] && [ -d "$log_dir" ] && [ ! -L "$log_dir" ] || continue
    log_path="$log_dir/offtheroad-launcher-error.$$.log"
    if (umask 077; set -C; printf '%s\n' \
      '== Off The Road | nxbootstrap 0.6.37 | pre-runtime failure ==' \
      "status=$status pid=$$" "launcher=${BASH_SOURCE[0]:-$0}" \
      "game_dir=${GAMEDIR:-unresolved}" "cfw=${CFW_NAME:-unknown}" > "$log_path") 2>/dev/null; then
      printf 'nxbootstrap: pre-runtime failure; log=%s\n' "$log_path" >&2
      return 0
    fi
  done
  printf 'nxbootstrap: pre-runtime failure; no writable diagnostic path\n' >&2
}
nxbootstrap_release_fallback_lock() {
  local owner_file owner_line owner_extra
  [ "${NXBOOTSTRAP_FALLBACK_LOCK_ACQUIRED:-0}" = 1 ] || return 0
  [ -n "${NXBOOTSTRAP_FALLBACK_LOCK_DIR:-}" ] && \
    [ "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" = "${NXBOOTSTRAP_LOCK_FILE:-}.d" ] && \
    [ -n "${NXBOOTSTRAP_FALLBACK_LOCK_TOKEN:-}" ] || {
      echo "WARNING: fallback instance lock ownership state is incomplete; refusing to release it"
      return 0
    }
  owner_file="$NXBOOTSTRAP_FALLBACK_LOCK_DIR/owner"
  if [ ! -d "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" ] || \
     [ -L "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" ] || \
     [ ! -O "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" ] || \
     [ ! -f "$owner_file" ] || [ -L "$owner_file" ] || \
     [ ! -O "$owner_file" ]; then
    echo "WARNING: fallback instance lock identity changed; refusing to release it"
    return 0
  fi
  { exec 7<"$owner_file"; } 2>/dev/null || {
    echo "WARNING: fallback instance lock owner is unreadable; refusing to release it"
    return 0
  }
  owner_line=
  owner_extra=
  if ! IFS= read -r owner_line <&7 || \
     IFS= read -r owner_extra <&7 || [ -n "$owner_extra" ] || \
     ! [ "$owner_file" -ef /proc/self/fd/7 ] || \
     [ "$owner_line" != "pid=$$ token=$NXBOOTSTRAP_FALLBACK_LOCK_TOKEN" ]; then
    { exec 7>&-; } 2>/dev/null || true
    echo "WARNING: fallback instance lock owner does not match this launcher; refusing to release it"
    return 0
  fi
  if ! rm -f -- "$owner_file"; then
    { exec 7>&-; } 2>/dev/null || true
    echo "WARNING: fallback instance lock owner could not be removed; lock remains closed"
    return 0
  fi
  { exec 7>&-; } 2>/dev/null || true
  if ! rmdir "$NXBOOTSTRAP_FALLBACK_LOCK_DIR" 2>/dev/null; then
    echo "WARNING: fallback instance lock directory is not empty; lock remains closed"
    return 0
  fi
  NXBOOTSTRAP_FALLBACK_LOCK_ACQUIRED=0
  NXBOOTSTRAP_FALLBACK_LOCK_DIR=""
  NXBOOTSTRAP_FALLBACK_LOCK_TOKEN=""
}
nxbootstrap_on_exit() {
  local status=$1
  # Only the launcher that acquired the no-flock mkdir lock may release it,
  # and only while its exact PID/run token still owns the stamped file.
  nxbootstrap_release_fallback_lock
  if [ -n "${NXBOOTSTRAP_HEALTH_FILE:-}" ]; then
    rm -f -- "$NXBOOTSTRAP_HEALTH_FILE" \
      "$NXBOOTSTRAP_HEALTH_FILE.tmp.$$" 2>/dev/null || true
  fi
  nxbootstrap_write_early_log "$status"
  nxbootstrap_finish
  return "$status"
}
nxbootstrap_install_exit_trap() {
  trap 'nxbootstrap_on_exit $?' EXIT
}
nxbootstrap_abort_before_game() {
  local abort_status=$1
  [ "$NXBOOTSTRAP_ABORTING" = 0 ] || return 0
  NXBOOTSTRAP_ABORTING=1
  echo "== aborted before game start (status $abort_status) =="
  nxbootstrap_finish
  exit "$abort_status"
}
nxbootstrap_install_early_traps() {
  trap 'nxbootstrap_abort_before_game 130' INT
  trap 'nxbootstrap_abort_before_game 143' TERM
  trap 'nxbootstrap_abort_before_game 129' HUP
}
nxbootstrap_install_exit_trap

# A signal before the game starts (mapper/extraction can take seconds) must
# still hand the screen back to the frontend instead of dying by default.
nxbootstrap_install_early_traps

# The EXIT trap is deliberately live before path discovery, PortMaster, controls
# or any other command that can fail.  Resolve the visible launcher only now.
NXBOOTSTRAP_LAUNCHER_DIR=$(CDPATH= cd -- "$(dirname -- "${BASH_SOURCE[0]:-$0}")" 2>/dev/null && pwd -P) || \
  NXBOOTSTRAP_LAUNCHER_DIR=""


XDG_DATA_HOME=${XDG_DATA_HOME:-$HOME/.local/share}
# Language / Idioma (supported / suportados: en).
# Edit only this value; adapters opt in through nxport.json.
GAME_LANGUAGE="en"
case "$GAME_LANGUAGE" in
  auto|en) ;;
  *) GAME_LANGUAGE="auto" ;;
esac
NXPORT_LANGUAGE=${NXPORT_LANGUAGE:-$GAME_LANGUAGE}
case "$NXPORT_LANGUAGE" in
  auto|en) ;;
  *) NXPORT_LANGUAGE=$GAME_LANGUAGE ;;
esac
NXBOOTSTRAP_LANGUAGE=$NXPORT_LANGUAGE
export NXPORT_LANGUAGE


# PortMaster publishes the integrated handheld stick count as ANALOGSTICKS;
# some CFW adapters use ANALOG_STICKS. Keep it as a validated host hint only:
# per-controller SDL bindings remain the authority for actual capabilities.
NXBOOTSTRAP_ANALOG_STICKS_HINT=""
unset NXINPUT_ANALOG_STICKS_HINT

# Safe CFW identity is diagnostic/mod-selection context only, never a quirk.
nxbootstrap_observe_cfw_name() {
  local candidate=""
  case "${CFW_NAME-}" in *[!A-Za-z0-9._-]*|'') unset CFW_NAME ;; *) return 0 ;; esac
  if [ -n "${HOME:-}" ] && [ -f "$HOME/.config/.OS" ] && \
     [ ! -L "$HOME/.config/.OS" ]; then
    IFS= read -r -n 65 candidate < "$HOME/.config/.OS" || true
  fi
  [ "${#candidate}" -le 64 ] || candidate=""
  case "$candidate" in *[!A-Za-z0-9._-]*|'') candidate="" ;; esac
  # dArkOSRE omits .OS: require two independent regular firmware artifacts.
  if [ -z "$candidate" ] && \
     [ -f /boot/arkos4clone-uboot.dtb ] && [ ! -L /boot/arkos4clone-uboot.dtb ] && \
     [ -f "/opt/system/Advanced/Backup dArkOS Settings.sh" ] && [ ! -L "/opt/system/Advanced/Backup dArkOS Settings.sh" ]; then
    candidate=dArkOSRE
  fi
  # ArkOS/TheRA/RetroOZ publish their identity in the plymouth title (same
  # source as PortMaster's device_info.txt); ELEC/JELOS/ROCKNIX/muOS/Knulli in
  # os-release OS_NAME/NAME. Plain ArkOS used to log cfw=none without .OS.
  local pfile=/usr/share/plymouth/themes/text.plymouth
  if [ -z "$candidate" ] && [ -f "$pfile" ] && [ ! -L "$pfile" ]; then
    candidate=$(grep -a -m1 '^title=' "$pfile" 2>/dev/null | cut -d= -f2- | cut -d' ' -f1 | tr -cd 'A-Za-z0-9._-' | cut -c1-64)
  fi
  if [ -z "$candidate" ] && [ -f /etc/os-release ] && [ ! -L /etc/os-release ]; then
    candidate=$(grep -a -m1 '^OS_NAME=' /etc/os-release 2>/dev/null | cut -d= -f2- | tr -d '"' | cut -d' ' -f1 | tr -cd 'A-Za-z0-9._-' | cut -c1-64)
    [ -n "$candidate" ] || candidate=$(grep -a -m1 '^NAME=' /etc/os-release 2>/dev/null | cut -d= -f2- | tr -d '"' | cut -d' ' -f1 | tr -cd 'A-Za-z0-9._-' | cut -c1-64)
    case "$candidate" in Debian|Ubuntu|Linux|Buildroot) candidate="" ;; esac
  fi
  case "$candidate" in *[!A-Za-z0-9._-]*|'') candidate="" ;; esac
  [ -n "$candidate" ] && CFW_NAME=$candidate
}
nxbootstrap_observe_cfw_name
# Find a real control.txt instead of stopping at the first empty PortMaster
# directory. The roots mirror the supported PortMaster/CFW layouts; the first
# valid regular control file keeps precedence.
controlfolder=""
# 23/08/2026: lista COMPLETA, espelho de nxbootstrap_default_portmaster_roots
# (a 0.5.1 conhecia 33 raizes e o launcher publicado so' 22 -- Miyoo/spruce,
# RetroDECK e cartoes com "Ports" maiusculo caiam no fallback sem controles).
# test-safety-static.sh trava a igualdade dos dois conjuntos.
NXBOOTSTRAP_PM_ROOTS=(
  "$(dirname "$(readlink -f "$0")")/PortMaster"
  "/opt/system/Tools/PortMaster" "/opt/tools/PortMaster"
  "$XDG_DATA_HOME/PortMaster"
  "${HOME:-/tmp}/.var/app/net.retrodeck.retrodeck/data/PortMaster"
  "/storage/.config/PortMaster"
  "/var/data/PortMaster" "/PortMaster"
  "/roms/tools/PortMaster" "/roms2/tools/PortMaster"
  "/storage/roms/ports/PortMaster" "/storage/roms/Ports/PortMaster"
  "/roms/ports/PortMaster" "/roms/Ports/PortMaster"
  "/roms2/ports/PortMaster" "/roms2/Ports/PortMaster"
  "/userdata/roms/ports/PortMaster" "/userdata/roms/Ports/PortMaster"
  "/userdata/system/.local/share/PortMaster"
  "/mnt/ports/PortMaster" "/mnt/Ports/PortMaster"
  "/mnt/mmc/MUOS/PortMaster" "/mnt/mmc/ports/PortMaster"
  "/mnt/mmc/Ports/PortMaster"
  "/mnt/mmc/roms/ports/PortMaster" "/mnt/mmc/ROMS/ports/PortMaster"
  "/mnt/SDCARD/Apps/PortMaster/PortMaster"
  "/mnt/sdcard/Roms/.portmaster/PortMaster"
  "/mnt/sdcard/MIYOO_EX/PortMaster"
  "/mnt/sdcard/ports/PortMaster" "/mnt/sdcard/Ports/PortMaster"
  "/mnt/sdcard/roms/ports/PortMaster" "/mnt/sdcard/ROMS/ports/PortMaster"
)
for NXBOOTSTRAP_PM_CANDIDATE in "${NXBOOTSTRAP_PM_ROOTS[@]}"; do
  [ -f "$NXBOOTSTRAP_PM_CANDIDATE/control.txt" ] && \
    [ ! -L "$NXBOOTSTRAP_PM_CANDIDATE/control.txt" ] || continue
  NXBOOTSTRAP_PM_REAL=$(readlink -f "$NXBOOTSTRAP_PM_CANDIDATE" 2>/dev/null) || continue
  [ -d "$NXBOOTSTRAP_PM_REAL" ] && \
    [ -f "$NXBOOTSTRAP_PM_REAL/control.txt" ] && \
    [ ! -L "$NXBOOTSTRAP_PM_REAL/control.txt" ] || continue
  controlfolder=$NXBOOTSTRAP_PM_REAL
  break
done
unset NXBOOTSTRAP_PM_ROOTS NXBOOTSTRAP_PM_CANDIDATE NXBOOTSTRAP_PM_REAL
[ -n "$controlfolder" ] || controlfolder="/storage/.config/PortMaster"

# Sourced firmware files must be regular (a symlinked control.txt/mod can
# point anywhere), and CFW_NAME reaches a source path so it must never carry
# a separator or shell-hostile byte.
if [ -f "$controlfolder/control.txt" ] && [ ! -L "$controlfolder/control.txt" ]; then
  source "$controlfolder/control.txt"
  nxbootstrap_install_exit_trap
  nxbootstrap_install_early_traps
  nxbootstrap_observe_cfw_name
  case "${CFW_NAME-}" in
    *[!A-Za-z0-9._-]*|'') NXBOOTSTRAP_MOD_NAME='' ;;
    *) NXBOOTSTRAP_MOD_NAME=$CFW_NAME ;;
  esac
  if [ -n "$NXBOOTSTRAP_MOD_NAME" ] && \
     [ -f "${controlfolder}/mod_${NXBOOTSTRAP_MOD_NAME}.txt" ] && \
     [ ! -L "${controlfolder}/mod_${NXBOOTSTRAP_MOD_NAME}.txt" ]; then
    source "${controlfolder}/mod_${NXBOOTSTRAP_MOD_NAME}.txt"
    nxbootstrap_install_exit_trap
    nxbootstrap_install_early_traps
  fi
  command -v get_controls >/dev/null 2>&1 && get_controls
  case "${ANALOGSTICKS:-${ANALOG_STICKS:-}}" in
    0|1|2)
      NXBOOTSTRAP_ANALOG_STICKS_HINT=${ANALOGSTICKS:-${ANALOG_STICKS:-}}
      export NXINPUT_ANALOG_STICKS_HINT="$NXBOOTSTRAP_ANALOG_STICKS_HINT"
      ;;
    *)
      NXBOOTSTRAP_ANALOG_STICKS_HINT=""
      unset NXINPUT_ANALOG_STICKS_HINT
      ;;
  esac
  nxbootstrap_install_exit_trap
  nxbootstrap_install_early_traps
  export NXCOMPAT_PORTMASTER_DIR="$controlfolder"
else
  unset NXCOMPAT_PORTMASTER_DIR
fi

# Two identities (V3-UPDATE-01). The LOGICAL dir is the path the frontend
# actually invoked (/roms/ports/<id>); it is the lexical identity handed to the
# guest -- a real Unity 6 completes its frame loop under the logical root.
# The PHYSICAL dir is `pwd -P` after cd; it is what framework security, inode
# containment and I/O use. `pwd -P` must NEVER silently replace /roms with
# /storage/roms in the guest's argument.
NXBOOTSTRAP_LOGICAL_GAMEDIR="/$directory/ports/offtheroad"
# The port dir a sibling of the ACTUALLY INVOKED launcher (readlink -f "$0"),
# used both as the fallback and to detect a two-tree divergence.
NXBOOTSTRAP_INVOKED_GAMEDIR="$(cd "$(dirname "$(readlink -f "$0")")" 2>/dev/null && pwd)/offtheroad"
NXBOOTSTRAP_GAMEDIR_REASON=frontend-directory
if [ ! -d "$NXBOOTSTRAP_LOGICAL_GAMEDIR" ]; then
  NXBOOTSTRAP_LOGICAL_GAMEDIR="$NXBOOTSTRAP_INVOKED_GAMEDIR"
  NXBOOTSTRAP_GAMEDIR_REASON=invoked-launcher-fallback
elif [ -d "$NXBOOTSTRAP_INVOKED_GAMEDIR" ] && \
     ! [ "$NXBOOTSTRAP_LOGICAL_GAMEDIR" -ef "$NXBOOTSTRAP_INVOKED_GAMEDIR" ]; then
  # /roms and /storage/roms are DISTINCT trees that BOTH hold this port: never
  # run the frontend's copy blindly. Prefer the tree the launcher was actually
  # invoked from (its own sibling), and record the divergence (NXU0007).
  echo "NXU0007: distinct port trees frontend=$NXBOOTSTRAP_LOGICAL_GAMEDIR invoked=$NXBOOTSTRAP_INVOKED_GAMEDIR; preferring the invoked launcher's tree" >&2
  NXBOOTSTRAP_LOGICAL_GAMEDIR="$NXBOOTSTRAP_INVOKED_GAMEDIR"
  NXBOOTSTRAP_GAMEDIR_REASON=invoked-launcher-over-divergent-tree
fi
GAMEDIR="$NXBOOTSTRAP_LOGICAL_GAMEDIR"  # provisional: the ATTEMPTED dir, so an
                                        # early failure records it, not "unresolved"
cd "$GAMEDIR" || exit 1
GAMEDIR=$(pwd -P)                       # physical: framework security and I/O
NXBOOTSTRAP_PHYSICAL_GAMEDIR="$GAMEDIR"

# Record whether this run could put an image on the panel at all.  A launch
# from a remote shell can fail to open a window for reasons that have nothing
# to do with the game, and a black frame collected that way is evidence about
# the harness, not the port.  The frontend starts us with no SSH_* in the
# environment; a remote operator always carries them.
if [ -z "$SSH_CONNECTION" ] && [ -z "$SSH_TTY" ] && [ -z "$SSH_CLIENT" ]; then
  export NXLAUNCH_FRONTEND=1
fi

# Wayland firmwares (ROCKNIX/sway) try to fullscreen the port window by
# app_id derived from the port name; an SDL window without an explicit app id
# never matches and their helper retries into the log forever.  Naming the
# window costs nothing elsewhere and turns that helper into a working
# fullscreen.  Inherited values win (a CFW that sets its own id knows better).
[ -n "${SDL_APP_ID:-}" ] || export SDL_APP_ID="offtheroad"
[ -n "${SDL_VIDEO_WAYLAND_WMCLASS:-}" ] || \
  export SDL_VIDEO_WAYLAND_WMCLASS="offtheroad"

# Two previous generations survive: the run that showed the bug is often the
# one BEFORE the run that collected the log.
[ -s "$GAMEDIR/log.prev.txt" ] && mv -f "$GAMEDIR/log.prev.txt" "$GAMEDIR/log.prev2.txt" 2>/dev/null
[ -s "$GAMEDIR/log.txt" ] && mv -f "$GAMEDIR/log.txt" "$GAMEDIR/log.prev.txt" 2>/dev/null
[ -s "$GAMEDIR/events.jsonl" ] && [ ! -L "$GAMEDIR/events.jsonl" ] && \
  mv -f "$GAMEDIR/events.jsonl" "$GAMEDIR/events.prev.jsonl" 2>/dev/null
if ! exec > "$GAMEDIR/log.txt" 2>&1; then
  printf 'nxbootstrap: cannot open the runtime log\n' >&2
  exit 1
fi
if ! echo "== Off The Road | nxbootstrap 0.6.37 | cfw=${CFW_NAME:-none} =="; then
  exit 1
fi
NXBOOTSTRAP_EARLY_LOG_ACTIVE=0
# Sanitized path receipt (V3-UPDATE-01): both identities and the choice, so a
# silent /roms -> /storage/roms swap is visible in the log, never hidden.
if [ "$NXBOOTSTRAP_LOGICAL_GAMEDIR" = "$NXBOOTSTRAP_PHYSICAL_GAMEDIR" ]; then
  echo "gamedir logical=$NXBOOTSTRAP_LOGICAL_GAMEDIR physical=same selection=$NXBOOTSTRAP_GAMEDIR_REASON"
else
  echo "gamedir logical=$NXBOOTSTRAP_LOGICAL_GAMEDIR physical=$NXBOOTSTRAP_PHYSICAL_GAMEDIR selection=$NXBOOTSTRAP_GAMEDIR_REASON root=symlinked-same-inode"
fi

# Durable latest-boundary record.  Every transition is published by an
# exclusive temporary file and rename before the following phase can begin.
# Runtime adapters receive the same schema/path and remain the authority for
# video-provider and first-frame observations; the launcher never fabricates
# either event or inserts a pipe into the native process flow.
NXBOOTSTRAP_PHASE_SEQUENCE=0
NXBOOTSTRAP_PHASE_FILE="$GAMEDIR/nxphase-result.json"
NXOBS_PHASE_PROTOCOL=nxbootstrap-phase-v1
NXOBS_PHASE_FILE=$NXBOOTSTRAP_PHASE_FILE
NXOBS_EVENT_PROTOCOL=nx-event-v1
NXOBS_EVENT_SINK=stdout
NXOBS_RUN_ID=offtheroad-$$
# V3-OBS-01: one non-reusable run id crosses launcher, NXExtract, adapter,
# loader and game. PID alone repeats across reboots; add wall-clock (only as
# entropy, never authority) and $RANDOM.
NXOBS_RUN_ID="$NXOBS_RUN_ID-$(date +%s 2>/dev/null || printf 0)-$RANDOM"
NXOBS_EVENTS_FILE="$GAMEDIR/events.jsonl"
NXOBS_BOOTSTRAP_VERSION=0.6.37
NXOBS_PHASE_SCHEMA_VERSION=1
export NXOBS_PHASE_PROTOCOL NXOBS_PHASE_FILE NXOBS_EVENT_PROTOCOL \
  NXOBS_EVENT_SINK NXOBS_RUN_ID NXOBS_BOOTSTRAP_VERSION \
  NXOBS_PHASE_SCHEMA_VERSION NXOBS_EVENTS_FILE
nxbootstrap_phase_event() {
  local phase=$1 boundary=$2 source=$3 reason_code=$4 child_status=${5:-}
  local event_status phase_tmp child_json event_details
  case "$phase" in ''|*[!A-Za-z0-9._-]*) return 2 ;; esac
  case "$source" in
    bootstrap|extractor|loader|graphics|audio|input|lifecycle|diagnostic) ;;
    *) return 2 ;;
  esac
  case "$reason_code" in ''|*[!0-9]*) return 2 ;; esac
  [ "$reason_code" -le 9999 ] 2>/dev/null || return 2
  case "$boundary" in
    START) event_status=begin ;;
    OK) event_status=ok ;;
    ERROR) event_status=failed ;;
    OBSERVED) event_status=observed ;;
    EXIT)
      case "$child_status" in ''|*[!0-9]*) return 2 ;; esac
      if [ "$child_status" -eq 0 ]; then event_status=ok; else event_status=failed; fi
      ;;
    *) return 2 ;;
  esac
  case "$child_status" in
    '') child_json=null; event_details='{}' ;;
    *[!0-9]*) return 2 ;;
    *) child_json=$child_status; event_details="{\"child_status\":$child_status}" ;;
  esac
  if [ -L "$NXBOOTSTRAP_PHASE_FILE" ] || [ -d "$NXBOOTSTRAP_PHASE_FILE" ]; then
    echo "ERROR: phase result path is unsafe"
    return 1
  fi
  NXBOOTSTRAP_PHASE_SEQUENCE=$((NXBOOTSTRAP_PHASE_SEQUENCE + 1))
  phase_tmp="$GAMEDIR/.nxphase-result.json.tmp.$$.$NXBOOTSTRAP_PHASE_SEQUENCE.$RANDOM"
  if ! (umask 077; set -C; printf '%s\n' \
    "{\"schema\":\"org.nextos.nxbootstrap.phase-result\",\"schema_version\":1,\"nxbootstrap_version\":\"0.6.37\",\"sequence\":$NXBOOTSTRAP_PHASE_SEQUENCE,\"run_id\":\"$NXOBS_RUN_ID\",\"source\":\"$source\",\"phase\":\"$phase\",\"boundary\":\"$boundary\",\"status\":\"$event_status\",\"reason_code\":$reason_code,\"child_status\":$child_json,\"pid\":$$}" \
    > "$phase_tmp" && mv -f "$phase_tmp" "$NXBOOTSTRAP_PHASE_FILE"); then
    rm -f "$phase_tmp" 2>/dev/null || true
    echo "ERROR: could not publish phase boundary: $phase $boundary"
    return 1
  fi
  if [ "$boundary" = EXIT ]; then
    printf 'PHASE %s EXIT status=%s\n' "$phase" "$child_status"
  else
    printf 'PHASE %s %s\n' "$phase" "$boundary"
  fi
  printf 'NXEVENT {"schema":"nx-event-v1","source":"%s","phase":"%s","status":"%s","reason_code":%s,"details":%s}\n' \
    "$source" "$phase" "$event_status" "$reason_code" "$event_details"
  if [ -n "${NXOBS_EVENTS_FILE:-}" ] && [ ! -L "$NXOBS_EVENTS_FILE" ] && \
     [ ! -d "$NXOBS_EVENTS_FILE" ]; then
    printf '{"schema":"nx-event-v1","schema_version":1,"run_id":"%s","sequence":%s,"source":"%s","component":"nxbootstrap","component_version":"0.6.37","phase":"%s","status":"%s","reason_code":%s,"details":%s}\n' \
      "$NXOBS_RUN_ID" "$NXBOOTSTRAP_PHASE_SEQUENCE" "$source" "$phase" \
      "$event_status" "$reason_code" "$event_details" \
      >> "$NXOBS_EVENTS_FILE" 2>/dev/null || true
  fi
}

# V3-UPDATE-01/NXU####: structured update/generation receipt helper.
nxbootstrap_update_event() {
  local code=$1 detail=$2
  case "$code" in NXU[0-9][0-9][0-9][0-9]) ;; *) return 2 ;; esac
  echo "UPDATE $code: $detail"
  if [ -n "${NXOBS_EVENTS_FILE:-}" ] && [ ! -L "$NXOBS_EVENTS_FILE" ]; then
    printf '{"schema":"nx-event-v1","schema_version":1,"run_id":"%s","source":"bootstrap","component":"nxbootstrap","component_version":"0.6.37","phase":"generation","status":"observed","code":"%s","details":{"note":"%s"}}\n' \
      "$NXOBS_RUN_ID" "$code" "$detail" >> "$NXOBS_EVENTS_FILE" 2>/dev/null || true
  fi
}
# V3-RUNTIME-01/NXR####: structured RUNTIME (single-instance/reaper) event -- a
# DISTINCT family from the NXU update/generation codes. Routing an NXR code
# through nxbootstrap_update_event silently dropped it (the NXU#### case did not
# match, so the helper returned 2 with no log line at all).
nxbootstrap_runtime_event() {
  local code=$1 detail=$2
  case "$code" in NXR[0-9][0-9][0-9][0-9]) ;; *) return 2 ;; esac
  echo "RUNTIME $code: $detail"
  if [ -n "${NXOBS_EVENTS_FILE:-}" ] && [ ! -L "$NXOBS_EVENTS_FILE" ]; then
    printf '{"schema":"nx-event-v1","schema_version":1,"run_id":"%s","source":"bootstrap","component":"nxbootstrap","component_version":"0.6.37","phase":"runtime","status":"observed","code":"%s","details":{"note":"%s"}}\n' \
      "$NXOBS_RUN_ID" "$code" "$detail" >> "$NXOBS_EVENTS_FILE" 2>/dev/null || true
