# --- V3-UPDATE-01 / V3-ROLLBACK-01 / V3-CLOCK-01 ------------------------------
# Immutable side-by-side generations under $GAMEDIR/.nxruntime/generations.
# Selection NEVER uses mtime/ctime/filename ordering: only the launcher's own
# baked generation id, the commit markers and the atomic local state. A hybrid
# member-by-member install (old launcher + new runtime, or the reverse) is
# detected by content hash and SELF-HEALED from the chosen complete
# generation; owner data (gamedata, saves, NEXTOSCONTROLLERS.gptk,
# NEXTOSSETTINGS.txt) is never touched. Nothing here deletes a generation.
NXBOOTSTRAP_GENERATION_ID=d09c4da5ac53c62aae1f895efe51b80e187a316acf840b733ddf37790eaf0692
NXBOOTSTRAP_GENERATION_FORMAT=2
NXBOOTSTRAP_GENERATION_NXEXTRACT=1
NXRUNTIME_DIR="$GAMEDIR/.nxruntime"
NXRUNTIME_STATE="$NXRUNTIME_DIR/state.json"
nxbootstrap_state_field() {
  # state.json is one flat JSON line written only by this launcher/nxdoctor.
  sed -n 's/.*"'"$1"'":"\{0,1\}\([A-Za-z0-9_-]*\)"\{0,1\}.*/\1/p' \
    "$NXRUNTIME_STATE" 2>/dev/null | head -n 1
