  local failure_generation=${6:-null} last_health_run_id=${7:-null} state_tmp
  nxbootstrap_state_id_or_null "$active" || return 1
  nxbootstrap_state_id_or_null "$pending" || return 1
  nxbootstrap_state_id_or_null "$previous" || return 1
  nxbootstrap_state_id_or_null "$failure_generation" || return 1
  case "$seq:$failures" in *[!0-9:]*) return 1 ;; esac
  case "$last_health_run_id" in
    null) ;;
    ''|*[!A-Za-z0-9._-]*) return 1 ;;
  esac
  [ "${#last_health_run_id}" -le 192 ] || return 1
  [ -d "$NXRUNTIME_DIR" ] || mkdir -p "$NXRUNTIME_DIR" 2>/dev/null || return 1
  state_tmp="$NXRUNTIME_DIR/.state.json.tmp.$$.$RANDOM"
  if (umask 077; set -C; printf '%s\n' \
    "{\"schema\":\"nxruntime-state-v2\",\"schema_version\":2,\"active\":\"$active\",\"pending\":\"$pending\",\"previous_healthy\":\"$previous\",\"activation_seq\":$seq,\"prehealth_failures\":$failures,\"failure_generation\":\"$failure_generation\",\"last_health_run_id\":\"$last_health_run_id\"}" \
    > "$state_tmp") && mv -f "$state_tmp" "$NXRUNTIME_STATE"; then
