  case "$path" in /*) return 1 ;; esac
  case "/$path/" in *'/../'*|*'/./'*|*'//'* ) return 1 ;; esac
  case "$path" in
    gamedata|gamedata/*|saves|saves/*|NEXTOSCONTROLLERS.gptk|NEXTOSSETTINGS.txt)
      return 1 ;;
  esac
  return 0
}
nxbootstrap_real_file_below() {
  local root=$1 relative=$2 cursor=$1 part index
  local -a parts=()
  nxbootstrap_relative_path_safe "$relative" || return 1
  IFS=/ read -r -a parts <<< "$relative"
  for ((index=0; index<${#parts[@]}-1; index++)); do
    part=${parts[index]}
    cursor="$cursor/$part"
    [ -d "$cursor" ] && [ ! -L "$cursor" ] || return 1
  done
  cursor="$root/$relative"
  [ -f "$cursor" ] && [ ! -L "$cursor" ]
}
nxbootstrap_filesystem_is_chmodless() {
  # FAT/exFAT/FUSE deployments can expose every regular file as 0777 and
  # silently ignore chmod.  Prove that property in the same directory before
  # accepting the mount's synthetic mode; never infer it from one file.
  local directory=$1 probe metadata actual
  [ -d "$directory" ] && [ ! -L "$directory" ] || return 1
  probe="$directory/.nxmode-probe.$$.$RANDOM"
  rm -f -- "$probe" 2>/dev/null || true
  if ! (umask 077; set -C; : > "$probe") 2>/dev/null || \
     [ ! -f "$probe" ] || [ -L "$probe" ]; then
    rm -f -- "$probe" 2>/dev/null || true
    return 1
  fi
  chmod 0600 "$probe" 2>/dev/null || {
    rm -f -- "$probe" 2>/dev/null || true
    return 1
  }
  chmod 0644 "$probe" 2>/dev/null || {
    rm -f -- "$probe" 2>/dev/null || true
    return 1
  }
  metadata=$(LC_ALL=C command ls -Lld -- "$probe" 2>/dev/null) || {
    rm -f -- "$probe" 2>/dev/null || true
    return 1
  }
  actual=${metadata%% *}
  rm -f -- "$probe" 2>/dev/null || true
  # A POSIX filesystem ends at 0644.  Any other reported mode proves that
  # chmod did not establish the requested bits for this filesystem view.
  [ "$actual" != -rw-r--r-- ]
