nxbootstrap_file_mode_matches() {
  local path=$1 expected=$2 metadata actual directory
  metadata=$(LC_ALL=C command ls -Lld -- "$path" 2>/dev/null) || return 1
  actual=${metadata%% *}
  case "$expected:$actual" in
    0755:-rwxr-xr-x|0644:-rw-r--r--) return 0 ;;
  esac
  directory=${path%/*}
  [ "$directory" != "$path" ] || directory=.
  nxbootstrap_filesystem_is_chmodless "$directory" || return 1
  # On a chmodless filesystem the build/ZIP remains the authority for the
  # pinned mode. Runtime integrity still comes from regular/no-symlink/hash;
  # an executable additionally has to be executable in the mounted view.
  case "$expected:$actual" in
    0644:-?????????) return 0 ;;
    0755:-??x??????) return 0 ;;
  esac
  return 1
}
nxbootstrap_generation_format() {
  local generation_root=$1 line extra
  if [ -e "$generation_root/format" ] || [ -L "$generation_root/format" ]; then
    [ -f "$generation_root/format" ] && [ ! -L "$generation_root/format" ] || return 1
    IFS= read -r line < "$generation_root/format" || return 1
    [ "$line" = nxruntime-generation-v2 ] || return 1
    ! IFS= read -r extra < <(sed -n '2p' "$generation_root/format") || return 1
    grep -Fq '"schema": "nxruntime-generation-v2"' "$generation_root/manifest.json" 2>/dev/null || return 1
    grep -Fq '"schema_version": 2' "$generation_root/manifest.json" 2>/dev/null || return 1
    printf '2\n'
  else
    printf '1\n'
  fi
