  # only launcher+nxport and therefore can never be a rollback anchor for a v2
  # runtime closure.
  local generation_root=$1 component_line component_hash component_path
  local component_source component_actual component_count=0 saw_launcher=0 saw_manifest=0
  [ "$(nxbootstrap_generation_format "$generation_root")" = 1 ] || return 1
  [ -f "$generation_root/components.sha256" ] && \
    [ ! -L "$generation_root/components.sha256" ] || return 1
  while IFS= read -r component_line; do
    component_hash=${component_line%%  *}
    component_path=${component_line#*  }
    [ "$component_path" != "$component_line" ] || return 1
    [ "${#component_hash}" -eq 64 ] || return 1
    case "$component_hash" in *[!0-9a-f]*) return 1 ;; esac
    case "$component_path" in
      "launcher/Off The Road.sh") saw_launcher=$((saw_launcher + 1)) ;;
      nxport.json) saw_manifest=$((saw_manifest + 1)) ;;
      *) return 1 ;;
    esac
    component_count=$((component_count + 1))
    component_source="$generation_root/files/$component_path"
    [ -f "$component_source" ] && [ ! -L "$component_source" ] || return 1
    if command -v sha256sum >/dev/null 2>&1; then
      component_actual=$(sha256sum "$component_source" 2>/dev/null) || return 1
      component_actual=${component_actual%% *}
      [ "$component_actual" = "$component_hash" ] || return 1
    fi
