nxbootstrap_generation_v2_source_relative() {
  local role=$1 path=$2
  case "$role" in
    launcher) NXBOOTSTRAP_COMPONENT_SOURCE_RELATIVE="launcher/$path" ;;
    nxport) NXBOOTSTRAP_COMPONENT_SOURCE_RELATIVE=nxport.json ;;
    executable|private-library|runtime-hook|nxextract-recipe|nxextract-engine|\
      nxextract-runner|nxextract-runtime-env|nxextract-ui|nxextract-helper|\
      nxextract-spec|nxsplash)
      NXBOOTSTRAP_COMPONENT_SOURCE_RELATIVE="runtime/$path" ;;
    *) return 1 ;;
  esac
}
nxbootstrap_generation_v2_files_closed() {
  local generation_root=$1 role mode digest path extra entry relative
  local had_nullglob=0 had_dotglob=0 had_globstar=0
  local -a entries=()
  local -A expected=()
  while IFS=$'\t' read -r role mode digest path extra; do
    [ -n "$role" ] && [ -z "$extra" ] || return 1
    nxbootstrap_generation_v2_source_relative "$role" "$path" || return 1
    expected["$NXBOOTSTRAP_COMPONENT_SOURCE_RELATIVE"]=1
  done < "$generation_root/components.v2"
  shopt -q nullglob && had_nullglob=1
  shopt -q dotglob && had_dotglob=1
  shopt -q globstar && had_globstar=1
  shopt -s nullglob dotglob globstar
  entries=("$generation_root/files"/**)
  [ "$had_nullglob" = 1 ] || shopt -u nullglob
  [ "$had_dotglob" = 1 ] || shopt -u dotglob
  [ "$had_globstar" = 1 ] || shopt -u globstar
  for entry in "${entries[@]}"; do
    if [ -d "$entry" ] && [ ! -L "$entry" ]; then continue; fi
    [ -f "$entry" ] && [ ! -L "$entry" ] || return 1
    relative=${entry#"$generation_root/files/"}
    [ "$relative" != "$entry" ] && \
      [ -n "${expected[$relative]+x}" ] || return 1
    unset 'expected[$relative]'
  done
