nxbootstrap_generation_v2_clean_stale_heal_temps() {
  # A power loss can leave an adjacent two-pass staging file behind. Remove
  # only our reserved, dead-PID namespace inside the framework-owned NXExtract
  # tree; owner paths outside it are never cleanup targets. A symlink,
  # malformed suffix or live creator fails closed and is never deleted.
  local generation_root=$1 role mode digest path extra target candidate suffix
  local creator nonce had_nullglob=0
  local -a candidates=()
  while IFS=$'\t' read -r role mode digest path extra; do
    [ -n "$role" ] && [ -z "$extra" ] || return 1
    case "$role" in
      nxextract-engine|nxextract-runner|nxextract-runtime-env|nxextract-ui|\
        nxextract-helper|nxextract-spec) ;;
      *) continue ;;
    esac
    nxbootstrap_component_target "$role" "$path" || return 1
    target="$NXBOOTSTRAP_COMPONENT_TARGET_ROOT/$NXBOOTSTRAP_COMPONENT_TARGET_RELATIVE"
    shopt -q nullglob && had_nullglob=1 || had_nullglob=0
    shopt -s nullglob
    candidates=("$target".nxheal.*.*)
    [ "$had_nullglob" = 1 ] || shopt -u nullglob
    for candidate in "${candidates[@]}"; do
      [ -f "$candidate" ] && [ ! -L "$candidate" ] || return 1
      suffix=${candidate#"$target.nxheal."}
      creator=${suffix%%.*}
      nonce=${suffix#*.}
      [ "$nonce" != "$suffix" ] || return 1
      case "$creator:$nonce" in
        *[!0-9:]*) return 1 ;;
        :*|*:|0:*|0[0-9]*:*) return 1 ;;
      esac
      [ ! -d "/proc/$creator" ] || return 1
      rm -f -- "$candidate" 2>/dev/null || return 1
      [ ! -e "$candidate" ] && [ ! -L "$candidate" ] || return 1
    done
  done < "$generation_root/components.v2"
}
nxbootstrap_generation_v2_authenticated() {
  local generation_root=$1 require_modes=${2:-1} role mode component_hash component_path extra
  local component_source component_actual source_relative listed_count role_rank
  local generation_name identity_actual identity_line identity_nxport
  local identity_launcher identity_runtime identity_record preimage_actual
  local identity_runtime_actual zero_generation previous_role_rank=-1
  local component_count=0 saw_launcher=0 saw_manifest=0 saw_executable=0 saw_splash=0
