  [ "$(nxbootstrap_generation_format "$generation_root")" = 2 ] || return 1
  [ -f "$generation_root/components.v2" ] && [ ! -L "$generation_root/components.v2" ] || return 1
  [ -f "$generation_root/components.sha256" ] && [ ! -L "$generation_root/components.sha256" ] || return 1
