  identity_line=$(grep -F '  "launcher_preimage_sha256": "' "$generation_root/identity.json") || return 1
  identity_launcher=${identity_line#*\"launcher_preimage_sha256\": \"}
  identity_launcher=${identity_launcher%\",}
