    [ "$saw_nxrecipe" -eq 1 ] && [ "$saw_nxengine" -eq 1 ] && \
      [ "$saw_nxrunner" -eq 1 ] && [ "$saw_nxenv" -eq 1 ] && \
      [ "$saw_nxui" -eq 1 ] || return 1
  else
    [ "$saw_nxrecipe" -eq 0 ] && [ "$saw_nxengine" -eq 0 ] && \
      [ "$saw_nxrunner" -eq 0 ] && [ "$saw_nxenv" -eq 0 ] && \
      [ "$saw_nxui" -eq 0 ] && [ "$saw_nxextra" -eq 0 ] || return 1
