nxbootstrap_generation_v2_complete() {
  local generation_root=$1 role mode component_hash component_path extra
  local source_relative component_source component_actual

  # PortMaster normalizes an extracted port recursively to 0777 on POSIX media.
  # Authenticate the complete generation first, without trusting or changing
  # those permission bits. Only an identity/path/type/SHA/closure-exact store is
  # eligible for normalization to the modes already authenticated in
  # components.v2. A second complete pass then requires the normalized modes.
  nxbootstrap_generation_v2_authenticated "$generation_root" 0 || return 1
  while IFS=$'\t' read -r role mode component_hash component_path extra; do
    [ -n "$role" ] && [ -z "$extra" ] || return 1
    case "$mode" in 0644|0755) ;; *) return 1 ;; esac
    nxbootstrap_generation_v2_source_relative "$role" "$component_path" || return 1
    source_relative=$NXBOOTSTRAP_COMPONENT_SOURCE_RELATIVE
    component_source="$generation_root/files/$source_relative"
    nxbootstrap_real_file_below "$generation_root/files" "$source_relative" || return 1
    component_actual=$(sha256sum "$component_source" 2>/dev/null) || return 1
    [ "${component_actual%% *}" = "$component_hash" ] || return 1
    if ! nxbootstrap_file_mode_matches "$component_source" "$mode"; then
      chmod "${mode#0}" "$component_source" 2>/dev/null || return 1
    fi
