# Saves and configuration stay inside the port directory.
export HOME="$GAMEDIR"
# An empty CFW mapping must not clobber a valid inherited one (contract:
# honor the existing mapping and only log when the CFW publishes nothing).
# V3-CONTROLLERS-01 / V3-SETTINGS-01 (blocker 4): materialize the owner's
# editable copies from the immutable defaults exactly once, ATOMICALLY and
# symlink-safe on the target, the .new candidate AND the receipt/pin. An
# edited copy is NEVER overwritten; an untouched copy migrates with a receipt;
# a customized copy receives the new default as a side-by-side ".new". Every
# write goes through nxbootstrap_atomic_install so a planted symlink at the
# destination or the temp path can never be followed, and an interruption
# always leaves the last valid configuration in place.
nxbootstrap_atomic_install() {
  # $1 source (regular, non-symlink)  $2 destination path
  local src=$1 dest=$2 dir base tmp
  [ -f "$src" ] && [ ! -L "$src" ] || return 1
  dir=$(dirname -- "$dest")
  [ -d "$dir" ] && [ ! -L "$dir" ] || return 1
  base=$(basename -- "$dest")
  tmp="$dir/.$base.nxtmp.$$.$RANDOM"
  # Create AND fill $tmp in ONE exclusive open: set -C makes the shell open the
  # redirect with O_CREAT|O_EXCL, which fails on any pre-existing path INCLUDING
  # a symlink (dangling or not), so a planted symlink is refused instead of
  # written through. The bytes go to that same descriptor -- there is no
  # close/reopen window to race, which was the TOCTOU in the earlier
  # ": > tmp" (create empty) then "cat > tmp" (reopen, unguarded) sequence.
  if ! ( umask 077; set -C; cat "$src" > "$tmp" ) 2>/dev/null; then
    rm -f "$tmp" 2>/dev/null; return 1
  fi
  chmod 0644 "$tmp" 2>/dev/null || true
  # mv replaces the destination inode (never writes through a symlinked dest).
  if mv -f "$tmp" "$dest" 2>/dev/null; then return 0; fi
  rm -f "$tmp" 2>/dev/null; return 1
}
nxbootstrap_atomic_write_line() {
  # $1 literal line  $2 destination path (pin/receipt) -- atomic, symlink-safe
  local line=$1 dest=$2 dir base tmp
  dir=$(dirname -- "$dest")
  [ -d "$dir" ] && [ ! -L "$dir" ] || return 1
  base=$(basename -- "$dest")
  tmp="$dir/.$base.nxtmp.$$.$RANDOM"
  ( umask 077; set -C; printf '%s\n' "$line" > "$tmp" ) 2>/dev/null || { rm -f "$tmp" 2>/dev/null; return 1; }
  if [ -L "$tmp" ]; then rm -f "$tmp" 2>/dev/null; return 1; fi
  mv -f "$tmp" "$dest" 2>/dev/null || { rm -f "$tmp" 2>/dev/null; return 1; }
}
for nxbootstrap_mutable in NEXTOSCONTROLLERS.gptk NEXTOSSETTINGS.txt; do
  nxbootstrap_default="$GAMEDIR/defaults/$nxbootstrap_mutable"
  nxbootstrap_target="$GAMEDIR/$nxbootstrap_mutable"
  [ -f "$nxbootstrap_default" ] && [ ! -L "$nxbootstrap_default" ] || continue
  nxbootstrap_default_pin="$GAMEDIR/.nxruntime/$nxbootstrap_mutable.default.sha256"
  if [ ! -e "$nxbootstrap_target" ] && [ ! -L "$nxbootstrap_target" ]; then
    if nxbootstrap_atomic_install "$nxbootstrap_default" "$nxbootstrap_target"; then
      echo "OWNER FILE: materialized $nxbootstrap_mutable from defaults/"
    fi
    if command -v sha256sum >/dev/null 2>&1; then
      [ -d "$GAMEDIR/.nxruntime" ] || ( umask 077; mkdir "$GAMEDIR/.nxruntime" ) 2>/dev/null || true
      nxbootstrap_hash=$(sha256sum "$nxbootstrap_default" 2>/dev/null); nxbootstrap_hash=${nxbootstrap_hash%% *}
      [ -n "$nxbootstrap_hash" ] && nxbootstrap_atomic_write_line "$nxbootstrap_hash" "$nxbootstrap_default_pin" || true
    fi
  elif [ -f "$nxbootstrap_target" ] && [ ! -L "$nxbootstrap_target" ] && \
       command -v sha256sum >/dev/null 2>&1 && [ -f "$nxbootstrap_default_pin" ] && \
       [ ! -L "$nxbootstrap_default_pin" ]; then
    read -r nxbootstrap_previous_default < "$nxbootstrap_default_pin" || nxbootstrap_previous_default=""
    nxbootstrap_current_default=$(sha256sum "$nxbootstrap_default" 2>/dev/null)
    nxbootstrap_current_default=${nxbootstrap_current_default%% *}
    if [ -n "$nxbootstrap_previous_default" ] && \
       [ "$nxbootstrap_current_default" != "$nxbootstrap_previous_default" ]; then
      nxbootstrap_owner_hash=$(sha256sum "$nxbootstrap_target" 2>/dev/null)
      nxbootstrap_owner_hash=${nxbootstrap_owner_hash%% *}
      if [ "$nxbootstrap_owner_hash" = "$nxbootstrap_previous_default" ]; then
        if nxbootstrap_atomic_install "$nxbootstrap_default" "$nxbootstrap_target"; then
          nxbootstrap_atomic_write_line "$nxbootstrap_current_default" "$nxbootstrap_default_pin" || true
          echo "OWNER FILE: $nxbootstrap_mutable was untouched; migrated to the new default (receipt)"
        fi
      elif [ ! -e "$nxbootstrap_target.new" ] && [ ! -L "$nxbootstrap_target.new" ]; then
        if nxbootstrap_atomic_install "$nxbootstrap_default" "$nxbootstrap_target.new"; then
          echo "OWNER FILE: $nxbootstrap_mutable is customized; new default saved as $nxbootstrap_mutable.new"
        fi
      fi
    fi
  fi
done

